public func SUIViewAlert(_ viewRef: UnsafeMutableRawPointer, _ titlePtr: UnsafePointer<CChar>, _ messagePtr: UnsafePointer<CChar>, _ stateRef: UnsafeMutableRawPointer) -> UnsafeMutableRawPointer {
    let base = Unmanaged<Box<AnyView>>.fromOpaque(viewRef).takeUnretainedValue().value
    let title = String(cString: titlePtr)
    let message = String(cString: messagePtr)
    let state = Unmanaged<BridgedIntState>.fromOpaque(stateRef).takeUnretainedValue()
    let view = AnyView(BridgedAlertView(base: base, title: title, message: message, state: state))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedAlertView: View {
    let base: AnyView
    let title: String
    let message: String
    var state: BridgedIntState

    var body: some View {
        base.alert(title, isPresented: Binding(
            get: { state.value != 0 },
            set: { if !$0 { state.value = 0 } }
        )) {
            Button("OK") {}
        } message: {
            Text(message)
        }
    }
}

