@_cdecl("SUIViewTruncationMode")
public func SUIViewTruncationMode(_ viewRef: UnsafeMutableRawPointer, _ mode: Int32) -> UnsafeMutableRawPointer {
    let base = Unmanaged<Box<AnyView>>.fromOpaque(viewRef).takeUnretainedValue().value
    let m: Text.TruncationMode
    switch mode {
    case 0: m = .head
    case 1: m = .middle
    case 2: m = .tail
    default: m = .tail
    }
    let view = AnyView(base.truncationMode(m))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

