public func SUIViewListStyle(_ viewRef: UnsafeMutableRawPointer, _ style: Int32) -> UnsafeMutableRawPointer {
    let base = Unmanaged<Box<AnyView>>.fromOpaque(viewRef).takeUnretainedValue().value
    let view: AnyView
    switch style {
    case 0: view = AnyView(base.listStyle(.automatic))
    case 1: view = AnyView(base.listStyle(.sidebar))
    case 2: view = AnyView(base.listStyle(.inset))
    case 3: view = AnyView(base.listStyle(.plain))
    default: view = AnyView(base.listStyle(.automatic))
    }
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

