@_cdecl("SUIViewFullScreenCover")
@MainActor
public func SUIViewFullScreenCover(_ viewRef: UnsafeMutableRawPointer, _ stateRef: UnsafeMutableRawPointer, _ contentRef: UnsafeMutableRawPointer) -> UnsafeMutableRawPointer {
    let base = Unmanaged<Box<AnyView>>.fromOpaque(viewRef).takeUnretainedValue().value
    let state = Unmanaged<BridgedIntState>.fromOpaque(stateRef).takeUnretainedValue()
    let coverContent = Unmanaged<Box<AnyView>>.fromOpaque(contentRef).takeUnretainedValue().value
    let view = AnyView(BridgedFullScreenCoverView(base: base, state: state, coverContent: coverContent))
    return Unmanaged.passRetained(Box(view)).toOpaque()
}

@MainActor
struct BridgedFullScreenCoverView: View {
    let base: AnyView
    var state: BridgedIntState
    let coverContent: AnyView

    var body: some View {
        // fullScreenCover is iOS-only; use sheet on macOS.
        #if os(iOS)
        base.fullScreenCover(isPresented: Binding(
            get: { state.value != 0 },
            set: { if !$0 { state.value = 0 } }
        )) {
            coverContent
        }
        #else
        base.sheet(isPresented: Binding(
            get: { state.value != 0 },
            set: { if !$0 { state.value = 0 } }
        )) {
            coverContent
        }
        #endif
    }
}
